<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><?= $this->include('pages/partials/page_heading') ?><section ng-controller="auditLogController" ng-cloak><div class="alert alert-danger" ng-if="errorMessage" ng-bind="errorMessage"></div><article class="card sitara-card"><header class="card-header"><div class="d-flex flex-column flex-md-row justify-content-between gap-3"><div><h2 class="sitara-card-title">Riwayat aktivitas</h2><p class="sitara-card-subtitle">Catatan sistem hanya dapat dilihat dan tidak dapat diubah.</p></div><form class="d-flex gap-2" ng-submit="load()"><select class="form-select form-select-sm" ng-model="filters.entity"><option value="">Semua entitas</option><option ng-repeat="x in entities" ng-value="x.entity_type" ng-bind="x.entity_type"></option></select><input class="form-control form-control-sm" placeholder="Cari aksi" ng-model="filters.action"><button class="btn btn-sm btn-primary">Terapkan</button></form></div></header><div class="table-responsive"><table class="table sitara-table"><thead><tr><th>Waktu</th><th>Pengguna</th><th>Aksi</th><th>Entitas</th><th>ID</th><th>IP</th><th></th></tr></thead><tbody><tr ng-repeat="x in datas"><td ng-bind="x.created_at"></td><td><div class="table-main" ng-bind="x.full_name||'Sistem'"></div><small ng-bind="x.username||'-'"></small></td><td ng-bind="x.action"></td><td ng-bind="x.entity_type"></td><td ng-bind="x.entity_id||'-'"></td><td ng-bind="x.ip_address||'-'"></td><td><button class="btn btn-sm btn-outline-primary" ng-click="detail(x)">Detail</button></td></tr><tr ng-if="!datas.length"><td colspan="7" class="sitara-empty">Belum ada audit log.</td></tr></tbody></table></div></article><div class="modal fade" id="auditDetailModal"><div class="modal-dialog modal-xl modal-dialog-centered modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h2 class="modal-title h5">Detail audit</h2><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-6"><h3 class="h6">Data sebelum</h3><pre class="bg-light p-3 rounded" ng-bind="detailData.old_values||'Tidak ada'"></pre></div><div class="col-md-6"><h3 class="h6">Data sesudah</h3><pre class="bg-light p-3 rounded" ng-bind="detailData.new_values||'Tidak ada'"></pre></div></div></div></div></div></div></section><script>window.SITARA_AUDIT_CONFIG=<?= json_encode(['baseUrl'=>site_url('audit-log')]) ?>;</script><?= $this->endSection() ?>
